begin;
-- GENERATED by scripts/gen-migrations.mjs from supabase/templates. Do not edit by hand.
-- Gate 25 (A6, D-059): succession law variables per client (step-up, holding ITBI/IR, collation, usufruct, fines,
-- assets abroad, protective clauses). Additive: new columns with conservative defaults; the save RPC accepts them.
alter table cw_prod.succession_profiles
  add column include_abroad           boolean not null default true,
  add column late_fine_pct            numeric(5,2) not null default 0 check (late_fine_pct between 0 and 50),
  add column step_up                  boolean not null default false,
  add column declared_cost_total      numeric(18,2) not null default 0 check (declared_cost_total >= 0 and declared_cost_total < 1e15),
  add column declared_cost_real_estate numeric(18,2) not null default 0 check (declared_cost_real_estate >= 0 and declared_cost_real_estate < 1e15),
  add column itbi_rate_pct            numeric(5,2) not null default 3 check (itbi_rate_pct between 0 and 10),
  add column integralize_at_cost      boolean not null default true,
  add column holding_setup_pct        numeric(5,2) not null default 1 check (holding_setup_pct between 0 and 10),
  add column holding_annual_cost      numeric(18,2) not null default 0 check (holding_annual_cost >= 0 and holding_annual_cost < 1e12),
  add column pf_rent_rate_pct         numeric(5,2) not null default 27.5 check (pf_rent_rate_pct between 0 and 27.5),
  add column usufruct_base_pct        numeric(5,2) not null default 100 check (usufruct_base_pct between 0 and 100),
  add column prior_donations          numeric(18,2) not null default 0 check (prior_donations >= 0 and prior_donations < 1e15),
  add column collation_dispensed      boolean not null default false,
  add column clauses                  text[] not null default '{}'
    check (clauses <@ array['INALIENABILIDADE', 'IMPENHORABILIDADE', 'INCOMUNICABILIDADE', 'REVERSAO', 'USUFRUTO_VITALICIO']);

create or replace function cw_prod.succession_profile_save(p_client uuid, p_data jsonb) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not cw_prod_private.is_staff() then perform cw_prod_private.deny(); end if;
  perform cw_prod_private.require_client(p_client);
  insert into cw_prod.succession_profiles as s (client_id, domicile_uf, has_will, will_notes, donations_notes, inventory_kind, legal_fee_pct, court_costs_pct, other_costs)
  values (p_client, nullif(p_data ->> 'domicile_uf', ''), coalesce((p_data ->> 'has_will')::boolean, false), nullif(btrim(p_data ->> 'will_notes'), ''),
          nullif(btrim(p_data ->> 'donations_notes'), ''), coalesce(nullif(p_data ->> 'inventory_kind', ''), 'EXTRAJUDICIAL'),
          coalesce(nullif(p_data ->> 'legal_fee_pct', '')::numeric, 5), coalesce(nullif(p_data ->> 'court_costs_pct', '')::numeric, 1.5),
          coalesce(nullif(p_data ->> 'other_costs', '')::numeric, 0))
  on conflict (client_id) do update set domicile_uf = excluded.domicile_uf, has_will = excluded.has_will, will_notes = excluded.will_notes,
    donations_notes = excluded.donations_notes, inventory_kind = excluded.inventory_kind, legal_fee_pct = excluded.legal_fee_pct,
    court_costs_pct = excluded.court_costs_pct, other_costs = excluded.other_costs, updated_at = now();
  -- Law variables (A6): only the keys sent are changed, so the basic form keeps working on its own.
  if p_data ? 'law' then
    update cw_prod.succession_profiles set
      include_abroad = coalesce((p_data -> 'law' ->> 'include_abroad')::boolean, include_abroad),
      late_fine_pct = coalesce(nullif(p_data -> 'law' ->> 'late_fine_pct', '')::numeric, late_fine_pct),
      step_up = coalesce((p_data -> 'law' ->> 'step_up')::boolean, step_up),
      declared_cost_total = coalesce(nullif(p_data -> 'law' ->> 'declared_cost_total', '')::numeric, declared_cost_total),
      declared_cost_real_estate = coalesce(nullif(p_data -> 'law' ->> 'declared_cost_real_estate', '')::numeric, declared_cost_real_estate),
      itbi_rate_pct = coalesce(nullif(p_data -> 'law' ->> 'itbi_rate_pct', '')::numeric, itbi_rate_pct),
      integralize_at_cost = coalesce((p_data -> 'law' ->> 'integralize_at_cost')::boolean, integralize_at_cost),
      holding_setup_pct = coalesce(nullif(p_data -> 'law' ->> 'holding_setup_pct', '')::numeric, holding_setup_pct),
      holding_annual_cost = coalesce(nullif(p_data -> 'law' ->> 'holding_annual_cost', '')::numeric, holding_annual_cost),
      pf_rent_rate_pct = coalesce(nullif(p_data -> 'law' ->> 'pf_rent_rate_pct', '')::numeric, pf_rent_rate_pct),
      usufruct_base_pct = coalesce(nullif(p_data -> 'law' ->> 'usufruct_base_pct', '')::numeric, usufruct_base_pct),
      prior_donations = coalesce(nullif(p_data -> 'law' ->> 'prior_donations', '')::numeric, prior_donations),
      collation_dispensed = coalesce((p_data -> 'law' ->> 'collation_dispensed')::boolean, collation_dispensed),
      clauses = coalesce((select array_agg(x) from jsonb_array_elements_text(p_data -> 'law' -> 'clauses') x), case when p_data -> 'law' ? 'clauses' then '{}'::text[] else clauses end),
      updated_at = now()
     where client_id = p_client;
  end if;
end $$;
commit;
select 'migração 34 ok' as resultado, (select count(*) from information_schema.columns where table_schema = 'cw_prod' and table_name = 'succession_profiles' and column_name in ('step_up','clauses','prior_donations')) = 3 as colunas;
